    from_user = client.post("/users", json={"username": "from", "email": "from@example.com"}).json()
    t1 = client.post(
        "/tasks", json={"title": "A", "project_id": project["id"], "assignee_id": from_user["id"]}
    ).json()
    fake_id = t1["id"] + 9999

    resp = client.post(
        "/tasks/bulk-reassign", json={"task_ids": [t1["id"], fake_id], "to_assignee_id": user["id"]}
    )
