from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.orm import Session

from app import crud, schemas
from app.db.session import get_db
from app.models.task import TaskStatus

router = APIRouter(prefix="/tasks", tags=["tasks"])


@router.post("", response_model=schemas.TaskOut, status_code=201)
def create_task(payload: schemas.TaskCreate, db: Session = Depends(get_db)):
    return crud.create_task(db, payload)


@router.post("/bulk-reassign", response_model=list[schemas.TaskOut])
def bulk_reassign_tasks(payload: schemas.TaskBulkReassign, db: Session = Depends(get_db)):
    if crud.get_user(db, payload.to_assignee_id) is None:
        raise HTTPException(status_code=400, detail="to_assignee_id must reference an existing user")
    if len(payload.task_ids) == 0:
        raise HTTPException(status_code=400, detail="task_ids must not be empty")

    current = crud.count_active_tasks_for_assignee(db, payload.to_assignee_id)
    tasks = []
    for tid in payload.task_ids:
        task = crud.get_task(db, tid)
        if task is None:
            raise HTTPException(status_code=404, detail=f"task not found: {tid}")
        if task.status in (TaskStatus.todo, TaskStatus.in_progress) and task.assignee_id != payload.to_assignee_id:
            if current + 1 > crud.MAX_ACTIVE_TASKS_PER_ASSIGNEE:
                raise HTTPException(
                    status_code=409,
                    detail="reassignment would exceed destination assignee's maximum active tasks",
                )
            current += 1
        task.assignee_id = payload.to_assignee_id
        db.add(task)
        db.commit()
        db.refresh(task)
        tasks.append(task)
    return tasks


@router.get("", response_model=list[schemas.TaskOut])
